package app.unifeed.feed;
import java.time.Instant; import java.util.UUID; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/feed") public class FeedController {private final FeedService service;public FeedController(FeedService service){this.service=service;}
 @GetMapping FeedService.FeedPage page(Authentication auth,@RequestParam(defaultValue="20")int limit,@RequestParam(required=false)Instant cursorCreatedAt,@RequestParam(required=false)UUID cursorId,@RequestParam(name="cursor_created_at",required=false)Instant legacyCursorCreatedAt,@RequestParam(name="cursor_id",required=false)UUID legacyCursorId){return service.page(UUID.fromString(auth.getName()),limit,cursorCreatedAt==null?legacyCursorCreatedAt:cursorCreatedAt,cursorId==null?legacyCursorId:cursorId);} }
